import json
import asyncio
from playwright.async_api import async_playwright

def build_html():
    with open('/app/benchmark/source_data.json', 'r') as f:
        data = json.load(f)

    nasdaq = data['nasdaq_index']['data']
    pe = data['pe_ratio']['data']
    ipo = data['ipo_counts']['data']
    earnings = data['corporate_earnings']['data']

    html = f"""
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <title>Dot-com vs AI Bubble</title>
        <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
        <link href="https://fonts.googleapis.com/css2?family=Crimson+Pro:wght@400;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
        <style>
            :root {{
                --bg: #fdfcfb;
                --text: #1c1917;
                --text-dim: #78716c;
                --border: #e7e5e4;
                --dotcom: #be123c; /* Cranberry */
                --dotcom-bg: rgba(190, 18, 60, 0.1);
                --ai: #0369a1; /* Slate/Teal */
                --ai-bg: rgba(3, 105, 161, 0.1);
            }}
            body {{
                margin: 0;
                padding: 40px;
                background-color: var(--bg);
                color: var(--text);
                font-family: 'JetBrains Mono', monospace;
                width: 1200px;
            }}
            .header {{
                margin-bottom: 30px;
                border-bottom: 2px solid var(--border);
                padding-bottom: 20px;
            }}
            .title {{
                font-family: 'Crimson Pro', serif;
                font-size: 36px;
                font-weight: 700;
                margin: 0 0 10px 0;
            }}
            .subtitle {{
                font-family: 'Crimson Pro', serif;
                font-size: 20px;
                color: var(--text-dim);
                margin: 0;
            }}
            .legend {{
                display: flex;
                gap: 20px;
                margin-top: 20px;
                font-size: 14px;
                font-weight: 500;
            }}
            .legend-item {{
                display: flex;
                align-items: center;
                gap: 8px;
            }}
            .legend-color {{
                width: 16px;
                height: 16px;
                border-radius: 4px;
            }}
            .grid {{
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 30px;
            }}
            .chart-container {{
                background: #ffffff;
                border: 1px solid var(--border);
                border-radius: 8px;
                padding: 20px;
                box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);
            }}
            .chart-title {{
                font-family: 'Crimson Pro', serif;
                font-size: 20px;
                font-weight: 600;
                margin: 0 0 15px 0;
                text-align: center;
            }}
            canvas {{
                width: 100% !important;
                height: 300px !important;
            }}
        </style>
    </head>
    <body>
        <div class="header">
            <h1 class="title">Echoes of Exuberance: The AI Boom vs. The Dot-Com Bubble</h1>
            <p class="subtitle">Comparing NASDAQ trajectory, valuations, IPO frenzy, and corporate earnings across two eras of technological transformation.</p>
            <div class="legend">
                <div class="legend-item"><div class="legend-color" style="background: var(--dotcom)"></div> Dot-com Era (1997–2002)</div>
                <div class="legend-item"><div class="legend-color" style="background: var(--ai)"></div> AI Era (2021–2024)</div>
            </div>
        </div>
        <div class="grid">
            <div class="chart-container">
                <h2 class="chart-title">NASDAQ Composite Trajectory (Indexed to 100)</h2>
                <canvas id="chart1"></canvas>
            </div>
            <div class="chart-container">
                <h2 class="chart-title">Trailing 12-Month P/E Ratio</h2>
                <canvas id="chart2"></canvas>
            </div>
            <div class="chart-container">
                <h2 class="chart-title">Tech Sector IPOs per Year</h2>
                <canvas id="chart3"></canvas>
            </div>
            <div class="chart-container">
                <h2 class="chart-title">Aggregate Corporate Earnings (Billion USD)</h2>
                <canvas id="chart4"></canvas>
            </div>
        </div>

        <script>
            Chart.defaults.font.family = "'JetBrains Mono', monospace";
            Chart.defaults.color = '#78716c';
            Chart.defaults.plugins.legend.display = false;

            const labels = Array.from({{length: 24}}, (_, i) => `Q${i+1}`);

            // Reconstruct the dataset arrays matching the 0-23 offset range
            const dotcomNasdaq = new Array(24).fill(null);
            const aiNasdaq = new Array(24).fill(null);
            {nasdaq}.forEach(d => {{
                if(d.era === 'Dot-com') dotcomNasdaq[d.quarter_offset] = d.index_value;
                if(d.era === 'AI') aiNasdaq[d.quarter_offset] = d.index_value;
            }});

            const dotcomPe = new Array(24).fill(null);
            const aiPe = new Array(24).fill(null);
            {pe}.forEach(d => {{
                if(d.era === 'Dot-com') dotcomPe[d.quarter_offset] = d.pe;
                if(d.era === 'AI') aiPe[d.quarter_offset] = d.pe;
            }});

            // For annual data, we place it roughly at the middle or end of the year quarters (e.g. Q4, Q8, Q12)
            const dotcomIpo = new Array(24).fill(null);
            const aiIpo = new Array(24).fill(null);
            {ipo}.forEach(d => {{
                if(d.era === 'Dot-com') dotcomIpo[(d.year - 1997)*4 + 1] = d.ipo_count;
                if(d.era === 'AI') aiIpo[(d.year - 2021)*4 + 1] = d.ipo_count;
            }});

            const dotcomEarnings = new Array(24).fill(null);
            const aiEarnings = new Array(24).fill(null);
            {earnings}.forEach(d => {{
                if(d.era === 'Dot-com') dotcomEarnings[(d.year - 1997)*4 + 1] = d.earnings_bn;
                if(d.era === 'AI') aiEarnings[(d.year - 2021)*4 + 1] = d.earnings_bn;
            }});

            const commonOptions = {{
                responsive: true,
                maintainAspectRatio: false,
                scales: {{
                    x: {{ grid: {{ display: false }} }},
                    y: {{ border: {{ dash: [4, 4] }}, grid: {{ color: '#f5f5f4' }} }}
                }}
            }};

            // 1. NASDAQ Trajectory
            new Chart(document.getElementById('chart1'), {{
                type: 'line',
                data: {{
                    labels: labels,
                    datasets: [
                        {{ label: 'Dot-com', data: dotcomNasdaq, borderColor: '#be123c', borderWidth: 3, tension: 0.3, spanGaps: true }},
                        {{ label: 'AI', data: aiNasdaq, borderColor: '#0369a1', borderWidth: 3, tension: 0.3, spanGaps: true }}
                    ]
                }},
                options: {{ ...commonOptions, plugins: {{ annotation: {{ /* add peak annotations here */ }} }} }}
            }});

            // 2. P/E Ratio
            new Chart(document.getElementById('chart2'), {{
                type: 'line',
                data: {{
                    labels: labels,
                    datasets: [
                        {{ label: 'Dot-com', data: dotcomPe, borderColor: '#be123c', borderWidth: 2, borderDash: [5,5], pointBackgroundColor: '#be123c', spanGaps: true }},
                        {{ label: 'AI', data: aiPe, borderColor: '#0369a1', borderWidth: 2, borderDash: [5,5], pointBackgroundColor: '#0369a1', spanGaps: true }}
                    ]
                }},
                options: commonOptions
            }});

            // 3. IPO Count
            new Chart(document.getElementById('chart3'), {{
                type: 'bar',
                data: {{
                    labels: labels,
                    datasets: [
                        {{ label: 'Dot-com', data: dotcomIpo, backgroundColor: 'rgba(190, 18, 60, 0.8)', barPercentage: 1.0, categoryPercentage: 0.8 }},
                        {{ label: 'AI', data: aiIpo, backgroundColor: 'rgba(3, 105, 161, 0.8)', barPercentage: 1.0, categoryPercentage: 0.8 }}
                    ]
                }},
                options: commonOptions
            }});

            // 4. Corporate Earnings
            new Chart(document.getElementById('chart4'), {{
                type: 'bar',
                data: {{
                    labels: labels,
                    datasets: [
                        {{ label: 'Dot-com', data: dotcomEarnings, backgroundColor: 'rgba(190, 18, 60, 0.6)' }},
                        {{ label: 'AI', data: aiEarnings, backgroundColor: 'rgba(3, 105, 161, 0.6)' }}
                    ]
                }},
                options: commonOptions
            }});
        </script>
    </body>
    </html>
    """
    with open('/app/benchmark/index.html', 'w') as f:
        f.write(html)

async def capture():
    build_html()
    async with async_playwright() as p:
        browser = await p.chromium.launch(args=['--no-sandbox', '--disable-setuid-sandbox'])
        page = await browser.new_page(viewport={'width': 1280, 'height': 900}, device_scale_factor=2)
        await page.goto('file:///app/benchmark/index.html', wait_until='networkidle')
        # Wait a bit for Chart.js animations to complete
        await page.wait_for_timeout(2000)
        await page.screenshot(path='/app/output/result.png', full_page=True)
        await browser.close()

if __name__ == '__main__':
    asyncio.run(capture())
