                        const offset = (d.year - startYearDotcom) * 4 + 3;
                        if (offset < 24) dotcom[offset] = d[field];
                    }
                    if (d.era === 'AI') {
                        const offset = (d.year - startYearAi) * 4 + 3;
                        if (offset < 24) ai[offset] = d[field];
